import{_ as t,c as o,o as a,ae as s}from"./chunks/framework.ixH79I-5.js";const r="/BetterKMR/docs/assets/creating_custom_themes_p1.CXm0S0RJ.png",n="/BetterKMR/docs/assets/creating_custom_themes_p2.XUNHxluU.png",i="/BetterKMR/docs/assets/creating_custom_themes_p3.CZuUhvdH.png",h="/BetterKMR/docs/assets/creating_custom_themes_p4.Djp9WxB5.png",l="/BetterKMR/docs/assets/creating_custom_themes_p5.Co0Qbakp.png",d="/BetterKMR/docs/assets/creating_custom_themes_p6.C5sJvfBO.png",c="/BetterKMR/docs/assets/creating_custom_themes_p7.BRWHXBjp.png",w=JSON.parse(`{"title":"🏄 Creating Custom Themes","description":"With the release of v1.0, creating custom themes are now entirely possible (in beta)! In this guide, you'll be directed step-by-step on how to make brilliant themes.","frontmatter":{"title":"🏄 Creating Custom Themes","description":"With the release of v1.0, creating custom themes are now entirely possible (in beta)! In this guide, you'll be directed step-by-step on how to make brilliant themes."},"headers":[],"relativePath":"guides/creating_custom_themes.md","filePath":"guides/creating_custom_themes.md"}`),u={name:"guides/creating_custom_themes.md"};function m(g,e,p,b,y,_){return a(),o("div",null,e[0]||(e[0]=[s('<h1 id="🏄-creating-custom-themes" tabindex="-1">🏄 Creating Custom Themes <a class="header-anchor" href="#🏄-creating-custom-themes" aria-label="Permalink to &quot;🏄 Creating Custom Themes&quot;">​</a></h1><p><b style="color:#ff0000;">NOTE: This is old and only has the Code Editor. A guide for the Visual Theme Editor may be made soon.</b></p><p>With the release of v1.0, creating custom themes are now entirely possible (in beta)! In this guide, you&#39;ll be directed step-by-step on how to make brilliant themes.</p><p>First, click on the extension to open Settings. You can also click &quot;BetterKMR Menu&quot; in the &quot;My Account&quot; part of the navigation bar on your school&#39;s Kamar website.</p><table tabindex="0"><thead><tr><th style="text-align:center;"><img src="'+r+'" alt="Part 1 Image"></th></tr></thead><tbody><tr><td style="text-align:center;"><em>The BetterKMR extension, pinned to the URL bar. Also available through the &quot;Extensions&quot; button.</em></td></tr></tbody></table><p>From there, on the sidebar, click on the &quot;Themes&quot; tab and then click on the sub-tab &quot;Custom&quot;. You&#39;ll be greeted with something that looks like this:</p><table tabindex="0"><thead><tr><th style="text-align:center;"><img src="'+n+'" alt="Part 2 Image"></th></tr></thead><tbody><tr><td style="text-align:center;"><em>The &quot;Custom&quot; sub-tab on the Themes tab.</em></td></tr></tbody></table><p>By default (from a fresh install), you shouldn&#39;t have a list of your created themes yet (as image above). We&#39;ll need to start creating our theme, so go ahead and click on &quot;New&quot;. This opens up a somewhat intimidating window, where we have to input our theme name (call it anything you&#39;d like, as long as it&#39;s reasonable).</p><table tabindex="0"><thead><tr><th style="text-align:center;"><img src="'+i+'" alt="Part 3 Image"></th></tr></thead><tbody><tr><td style="text-align:center;"><em>The &quot;code editor&quot; as of v1.0. The code editor may look different depending on what version you&#39;re on.</em></td></tr></tbody></table><p>First of all, without doing anything else other than setting a name, you can click on Save. This will save your theme for you to use.</p><p><em>Note: You can use Ctrl+S (Windows/Linux/ChromeOS) or Cmd+S on Mac to save without pressing the button. Also, you can use Ctrl+Scroll on the Code Editor to zoom in/out.</em></p><p>Click on the Back button, and head back over to Themes -&gt; Custom. You should find your theme here!</p><table tabindex="0"><thead><tr><th style="text-align:center;"><img src="'+h+'" alt="Part 4 Image"></th></tr></thead><tbody><tr><td style="text-align:center;"><em>Our theme &quot;my-awesome-theme&quot; listed here in the themes we&#39;ve made.</em></td></tr></tbody></table><p>First off, the thing we should do is click <strong>Apply</strong>. This makes it so our theme is on our school&#39;s Kamar page now. Refresh or open a Kamar page, assuming you&#39;re logged in, then head over to Attendance.</p><table tabindex="0"><thead><tr><th style="text-align:center;"><img src="'+l+'" alt="Part 5 Image"></th></tr></thead><tbody><tr><td style="text-align:center;"><em>The current day highlighted as a light blue. Image is for example purposes only.</em></td></tr></tbody></table><p>Notice how today is highlighted a light blue colour? This is because of our custom theme we made — it sets today&#39;s background colour to light blue. So, how do we change it?</p><p>Head on back over to Themes -&gt; Custom. You&#39;ll notice the &quot;Edit&quot; button next to Apply. Click that and you&#39;ll head straight back to the Code Editor.</p><table tabindex="0"><thead><tr><th style="text-align:center;"><img src="'+d+'" alt="Part 6 Image"></th></tr></thead><tbody><tr><td style="text-align:center;"><em>Hovering over a &quot;square&quot; in the Code Editor, next to a hashtag, which is our colour.</em></td></tr></tbody></table><p>As shown above, the code seems somewhat self explanatory. It finds the day today, on the attendance, and sets the background colour to <strong>#409dc257</strong>. This strange bit of text looks odd, but it really is just light blue with a little bit of see-through transparency.</p><p>To change the colour, all we have to do is change the <strong>#409dc257</strong> to a different colour. For example, if we wanted to change it to red, we&#39;d change it to <strong>#c2404057</strong>.</p><table tabindex="0"><thead><tr><th style="text-align:center;"><img src="'+c+'" alt="Part 7 Image"></th></tr></thead><tbody><tr><td style="text-align:center;"><em>Hovering over a &quot;square&quot; in the Code Editor, next to a hashtag, which is our colour.</em></td></tr></tbody></table><p>But, however, fear not! There should be a little square next to the hashtag. Click on it and you&#39;ll see something that looks like the image above. You can play around with the colour picker to find the perfect colour for you! <em>By the way, the hashtag with a bunch of numbers and letters is called a hex code. It&#39;s a way of representing colours in code. You can use the color picker to find the hex code of any colour you want.</em></p><p>Once you&#39;re happy with the colour, click on the &quot;Apply&quot; button. This will save your changes and apply them to your school&#39;s Kamar page. Refresh or open a Kamar page, assuming you&#39;re logged in, then head over to Attendance. You can do this as many times as you like, switching tabs between the Code Editor and your school&#39;s Kamar page. Depending on what version you&#39;re on, you may be able to create as many themes as you like.</p><p>If you want to modify more than just &quot;today&#39;s date background colour&quot;, I recommend diving into CSS and using the Inspector. A good video can be found here: <a href="https://www.youtube.com/watch?v=Xb6ZIlYj2OY" target="_blank" rel="noreferrer">Using inspect element for CSS styles</a>. You can take inspiration from the default themes, or even use the default themes as a base to make your own! Check out the <a href="https://discord.gg/4MkRmFmHz2" target="_blank" rel="noreferrer">Discord server</a> if you need help.</p>',24)]))}const k=t(u,[["render",m]]);export{w as __pageData,k as default};
